        /// <summary>
        /// Layout of image and image subresources
        /// </summary>
        [VkVersion(VK_API_VERSION_1_0)]
        public enum VkImageLayout : uint
        {
            /// <summary>
            /// Specifies that the layout is unknown. Image memory cannot: be transitioned into this layout. This layout can: be used as the <see cref="M:initialLayout"/> member of <see cref="T:VkImageCreateInfo"/>. This layout can: be used in place of the current image layout in a layout transition, but doing so will cause the contents of the image's memory to be undefined:.
            /// </summary>
            VK_IMAGE_LAYOUT_UNDEFINED = unchecked((uint)0),
            
            /// <summary>
            /// Supports all types of device access.
            /// </summary>
            VK_IMAGE_LAYOUT_GENERAL = unchecked((uint)1),
            
            /// <summary>
            /// Must: only be used as a color or resolve attachment in a <see cref="T:VkFramebuffer"/>. This layout is valid only for image subresources of images created with the <see cref="T:VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT"/> usage bit enabled.
            /// </summary>
            VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL = unchecked((uint)2),
            
            /// <summary>
            /// Specifies a layout for both the depth and stencil aspects of a depth/stencil format image allowing read and write access as a depth/stencil attachment. It is equivalent to <see cref="T:VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL"/> and <see cref="T:VK_IMAGE_LAYOUT_STENCIL_ATTACHMENT_OPTIMAL"/>.
            /// </summary>
            VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL = unchecked((uint)3),
            
            /// <summary>
            /// Specifies a layout for both the depth and stencil aspects of a depth/stencil format image allowing read only access as a depth/stencil attachment or in shaders as a sampled image, combined image/sampler, or input attachment. It is equivalent to <see cref="T:VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL"/> and <see cref="T:VK_IMAGE_LAYOUT_STENCIL_READ_ONLY_OPTIMAL"/>. * <see cref="T:VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_STENCIL_ATTACHMENT_OPTIMAL"/> specifies a layout for depth/stencil format images allowing read and write access to the stencil aspect as a stencil attachment, and read only access to the depth aspect as a depth attachment or in shaders as a sampled image, combined image/sampler, or input attachment. It is equivalent to <see cref="T:VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL"/> and <see cref="T:VK_IMAGE_LAYOUT_STENCIL_ATTACHMENT_OPTIMAL"/>. * <see cref="T:VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_STENCIL_READ_ONLY_OPTIMAL"/> specifies a layout for depth/stencil format images allowing read and write access to the depth aspect as a depth attachment, and read only access to the stencil aspect as a stencil attachment or in shaders as a sampled image, combined image/sampler, or input attachment. It is equivalent to <see cref="T:VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL"/> and <see cref="T:VK_IMAGE_LAYOUT_STENCIL_READ_ONLY_OPTIMAL"/>.
            /// </summary>
            VK_IMAGE_LAYOUT_DEPTH_STENCIL_READ_ONLY_OPTIMAL = unchecked((uint)4),
            
            /// <summary>
            /// Specifies a layout allowing read-only access in a shader as a sampled image, combined image/sampler, or input attachment. This layout is valid only for image subresources of images created with the <see cref="T:VK_IMAGE_USAGE_SAMPLED_BIT"/> or <see cref="T:VK_IMAGE_USAGE_INPUT_ATTACHMENT_BIT"/> usage bits enabled.
            /// </summary>
            VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL = unchecked((uint)5),
            
            /// <summary>
            /// Must: only be used as a source image of a transfer command (see the definition of <see cref="T:VK_PIPELINE_STAGE_TRANSFER_BIT"/>). This layout is valid only for image subresources of images created with the <see cref="T:VK_IMAGE_USAGE_TRANSFER_SRC_BIT"/> usage bit enabled.
            /// </summary>
            VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL = unchecked((uint)6),
            
            /// <summary>
            /// Must: only be used as a destination image of a transfer command. This layout is valid only for image subresources of images created with the <see cref="T:VK_IMAGE_USAGE_TRANSFER_DST_BIT"/> usage bit enabled.
            /// </summary>
            VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL = unchecked((uint)7),
            
            /// <summary>
            /// Specifies that an image's memory is in a defined layout and can: be populated by data, but that it has not yet been initialized by the driver. Image memory cannot: be transitioned into this layout. This layout can: be used as the <see cref="M:initialLayout"/> member of <see cref="T:VkImageCreateInfo"/>. This layout is intended to be used as the initial layout for an image whose contents are written by the host, and hence the data can: be written to memory immediately, without first executing a layout transition. Currently, <see cref="T:VK_IMAGE_LAYOUT_PREINITIALIZED"/> is only useful with linear images because there is not a standard layout defined for <see cref="T:VK_IMAGE_TILING_OPTIMAL"/> images.
            /// </summary>
            VK_IMAGE_LAYOUT_PREINITIALIZED = unchecked((uint)8),
            
            VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_STENCIL_ATTACHMENT_OPTIMAL = unchecked((uint)1000117000),
            
            VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_STENCIL_READ_ONLY_OPTIMAL = unchecked((uint)1000117001),
            
            /// <summary>
            /// Specifies a layout for the depth aspect of a depth/stencil format image allowing read and write access as a depth attachment.
            /// </summary>
            VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL = unchecked((uint)1000241000),
            
            /// <summary>
            /// Specifies a layout for the depth aspect of a depth/stencil format image allowing read-only access as a depth attachment or in shaders as a sampled image, combined image/sampler, or input attachment.
            /// </summary>
            VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL = unchecked((uint)1000241001),
            
            /// <summary>
            /// Specifies a layout for the stencil aspect of a depth/stencil format image allowing read and write access as a stencil attachment.
            /// </summary>
            VK_IMAGE_LAYOUT_STENCIL_ATTACHMENT_OPTIMAL = unchecked((uint)1000241002),
            
            /// <summary>
            /// Specifies a layout for the stencil aspect of a depth/stencil format image allowing read-only access as a stencil attachment or in shaders as a sampled image, combined image/sampler, or input attachment.
            /// </summary>
            VK_IMAGE_LAYOUT_STENCIL_READ_ONLY_OPTIMAL = unchecked((uint)1000241003),
            
            /// <summary>
            /// Specifies a layout allowing read only access as an attachment, or in shaders as a sampled image, combined image/sampler, or input attachment.
            /// </summary>
            VK_IMAGE_LAYOUT_READ_ONLY_OPTIMAL = unchecked((uint)1000314000),
            
            /// <summary>
            /// Specifies a layout that must: only be used with attachment accesses in the graphics pipeline.
            /// </summary>
            VK_IMAGE_LAYOUT_ATTACHMENT_OPTIMAL = unchecked((uint)1000314001),
            
            /// <summary>
