        [VkVersion(VK_API_VERSION_1_0)]
        public enum VkPolygonMode : uint
        {
            /// <summary>
            /// Specifies that polygons are rendered using the polygon rasterization rules in this section.
            /// </summary>
            VK_POLYGON_MODE_FILL = unchecked((uint)0),
            
            /// <summary>
            /// Specifies that polygon edges are drawn as line segments.
            /// </summary>
            VK_POLYGON_MODE_LINE = unchecked((uint)1),
            
            /// <summary>
            /// Specifies that polygon vertices are drawn as points.
            /// </summary>
            VK_POLYGON_MODE_POINT = unchecked((uint)2),
            
            /// <summary>
            /// Specifies that polygons are rendered using polygon rasterization rules, modified to consider a sample within the primitive if the sample location is inside the axis-aligned bounding box of the triangle after projection. Note that the barycentric weights used in attribute interpolation can: extend outside the range [eq]#[0,1]# when these primitives are shaded. Special treatment is given to a sample position on the boundary edge of the bounding box. In such a case, if two rectangles lie on either side of a common edge (with identical endpoints) on which a sample position lies, then exactly one of the triangles must: produce a fragment that covers that sample during rasterization. + Polygons rendered in <see cref="T:VK_POLYGON_MODE_FILL_RECTANGLE_NV"/> mode may: be clipped by the frustum or by user clip planes. If clipping is applied, the triangle is culled rather than clipped. + Area calculation and facingness are determined for <see cref="T:VK_POLYGON_MODE_FILL_RECTANGLE_NV"/> mode using the triangle's vertices.
            /// </summary>
            VK_POLYGON_MODE_FILL_RECTANGLE_NV = unchecked((uint)1000153000),
            
            VK_POLYGON_MODE_MAX_ENUM = unchecked((uint)2147483647),
        }
        
