        /// <summary>
        /// Bitmask specifying additional parameters of an image
        /// </summary>
        [VkVersion(VK_API_VERSION_1_0)]
        [Flags]
        public enum VkImageCreateFlags : uint
        {
            /// <summary>
            /// Specifies that the image will be backed using sparse memory binding. This flag is not supported in Vulkan SC &lt;&lt;SCID-8&gt;&gt;.
            /// </summary>
            VK_IMAGE_CREATE_SPARSE_BINDING_BIT = unchecked((uint)1),
            
            /// <summary>
            /// Specifies that the image can: be partially backed using sparse memory binding. Images created with this flag must: also be created with the <see cref="T:VK_IMAGE_CREATE_SPARSE_BINDING_BIT"/> flag. This flag is not supported in Vulkan SC &lt;&lt;SCID-8&gt;&gt;.
            /// </summary>
            VK_IMAGE_CREATE_SPARSE_RESIDENCY_BIT = unchecked((uint)2),
            
            /// <summary>
            /// Specifies that the image will be backed using sparse memory binding with memory ranges that might also simultaneously be backing another image (or another portion of the same image). Images created with this flag must: also be created with the <see cref="T:VK_IMAGE_CREATE_SPARSE_BINDING_BIT"/> flag. This flag is not supported in Vulkan SC &lt;&lt;SCID-8&gt;&gt;.
            /// </summary>
            VK_IMAGE_CREATE_SPARSE_ALIASED_BIT = unchecked((uint)4),
            
            /// <summary>
            /// Specifies that the image can: be used to create a <see cref="T:VkImageView"/> with a different format from the image. For multi-planar formats, <see cref="T:VK_IMAGE_CREATE_MUTABLE_FORMAT_BIT"/> specifies that a <see cref="T:VkImageView"/> can be created of a _plane_ of the image.
            /// </summary>
            VK_IMAGE_CREATE_MUTABLE_FORMAT_BIT = unchecked((uint)8),
            
            /// <summary>
            /// Specifies that the image can: be used to create a <see cref="T:VkImageView"/> of type <see cref="T:VK_IMAGE_VIEW_TYPE_CUBE"/> or <see cref="T:VK_IMAGE_VIEW_TYPE_CUBE_ARRAY"/>.
            /// </summary>
            VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT = unchecked((uint)16),
            
            /// <summary>
            /// Specifies that two images created with the same creation parameters and aliased to the same memory can: interpret the contents of the memory consistently with each other, subject to the rules described in the Memory Aliasing section. This flag further specifies that each plane of a _disjoint_ image can: share an in-memory non-linear representation with single-plane images, and that a single-plane image can: share an in-memory non-linear representation with a plane of a multi-planar disjoint image, according to the rules in &lt;&lt;formats-compatible-planes&gt;&gt;. If the <see cref="M:pNext"/> chain includes a // Jon: logic needs to incorporate VK_VERSION_1_1 structure whose <see cref="M:handleTypes"/> member is not `0`, it is as if <see cref="T:VK_IMAGE_CREATE_ALIAS_BIT"/> is set. * <see cref="T:VK_IMAGE_CREATE_SAMPLE_LOCATIONS_COMPATIBLE_DEPTH_BIT_EXT"/> specifies that an image with a depth or depth/stencil format can: be used with custom sample locations when used as a depth/stencil attachment.
            /// </summary>
            VK_IMAGE_CREATE_ALIAS_BIT = unchecked((uint)1024),
            
            /// <summary>
            /// Specifies that the image can: be used with a non-zero value of the <see cref="M:splitInstanceBindRegionCount"/> member of a <see cref="T:VkBindImageMemoryDeviceGroupInfo"/> structure passed into <see cref="M:vkBindImageMemory2"/>. This flag also has the effect of making the image use the standard sparse image block dimensions. This flag is not supported in Vulkan SC &lt;&lt;SCID-8&gt;&gt;.
            /// </summary>
            VK_IMAGE_CREATE_SPLIT_INSTANCE_BIND_REGIONS_BIT = unchecked((uint)64),
            
            /// <summary>
            /// Specifies that the image can: be used to create a <see cref="T:VkImageView"/> of type <see cref="T:VK_IMAGE_VIEW_TYPE_2D"/> or <see cref="T:VK_IMAGE_VIEW_TYPE_2D_ARRAY"/>.
            /// </summary>
