        /// <summary>
        /// Bitmask of valid external semaphore handle types
        /// </summary>
        [VkVersion(VK_API_VERSION_1_1)]
        [Flags]
        public enum VkExternalSemaphoreHandleTypeFlags : uint
        {
            /// <summary>
            /// Specifies a POSIX file descriptor handle that has only limited valid usage outside of Vulkan and other compatible APIs. It must: be compatible with the POSIX system calls <c>dup</c>, <c>dup2</c>, <c>close</c>, and the non-standard system call <c>dup3</c>. Additionally, it must: be transportable over a socket using an <c>SCM_RIGHTS</c> control message. It owns a reference to the underlying synchronization primitive represented by its Vulkan semaphore object.
            /// </summary>
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_FD_BIT = unchecked((uint)1),
            
            /// <summary>
            /// Specifies an NT handle that has only limited valid usage outside of Vulkan and other compatible APIs. It must: be compatible with the functions <c>DuplicateHandle</c>, <c>CloseHandle</c>, <c>CompareObjectHandles</c>, <c>GetHandleInformation</c>, and <c>SetHandleInformation</c>. It owns a reference to the underlying synchronization primitive represented by its Vulkan semaphore object.
            /// </summary>
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_WIN32_BIT = unchecked((uint)2),
            
            /// <summary>
            /// Specifies a global share handle that has only limited valid usage outside of Vulkan and other compatible APIs. It is not compatible with any native APIs. It does not own a reference to the underlying synchronization primitive represented by its Vulkan semaphore object, and will therefore become invalid when all Vulkan semaphore objects associated with it are destroyed.
            /// </summary>
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_WIN32_KMT_BIT = unchecked((uint)4),
            
            /// <summary>
            /// Specifies an NT handle returned by <c>ID3D12Device</c> referring to a Direct3D 12 fence, or <c>ID3D11Device5</c> referring to a Direct3D 11 fence. It owns a reference to the underlying synchronization primitive associated with the Direct3D fence.
            /// </summary>
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_D3D12_FENCE_BIT = unchecked((uint)8),
            
            /// <summary>
            /// Specifies a POSIX file descriptor handle to a Linux Sync File or Android Fence object. It can be used with any native API accepting a valid sync file or fence as input. It owns a reference to the underlying synchronization primitive associated with the file descriptor. Implementations which support importing this handle type must: accept any type of sync or fence FD supported by the native system they are running on. * <see cref="T:VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_ZIRCON_EVENT_BIT_FUCHSIA"/> specifies a handle to a Zircon event object. It can be used with any native API that accepts a Zircon event handle. Zircon event handles are created with <c>ZX_RIGHTS_BASIC</c> and <c>ZX_RIGHTS_SIGNAL</c> rights. Vulkan on Fuchsia uses only the ZX_EVENT_SIGNALED bit when signaling or waiting.
            /// </summary>
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_SYNC_FD_BIT = unchecked((uint)16),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_ZIRCON_EVENT_BIT_FUCHSIA = unchecked((uint)128),
            
            /// <summary>
            /// An alias of <see cref="T:VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_D3D12_FENCE_BIT"/> with the same meaning. It is provided for convenience and code clarity when interacting with D3D11 fences.
            /// </summary>
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_D3D11_FENCE_BIT = unchecked((uint)8),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_FD_BIT_KHR = unchecked((uint)1),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_WIN32_BIT_KHR = unchecked((uint)2),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_WIN32_KMT_BIT_KHR = unchecked((uint)4),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_D3D12_FENCE_BIT_KHR = unchecked((uint)8),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_SYNC_FD_BIT_KHR = unchecked((uint)16),
            
            VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_FLAG_BITS_MAX_ENUM = unchecked((uint)2147483647),
        }
        
