            VK_DESCRIPTOR_BINDING_PARTIALLY_BOUND_BIT_EXT = unchecked((uint)4),
            
            VK_DESCRIPTOR_BINDING_VARIABLE_DESCRIPTOR_COUNT_BIT_EXT = unchecked((uint)8),
            
